import unittest

from hourglass.rounding import round_span_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_snaps_to_quarter_hours(self):
        labels = round_span_labels([Span(538, 1036)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_goes_up(self):
        labels = round_span_labels([Span(545, 600)], 10)
        self.assertEqual(labels, ["09:10-10:00 (0h 50m)"])

    def test_step_of_one_keeps_times(self):
        labels = round_span_labels([Span(540, 1050)], 1)
        self.assertEqual(labels, ["09:00-17:30 (8h 30m)"])

    def test_keeps_order_of_spans(self):
        labels = round_span_labels([Span(540, 600), Span(700, 760)], 60)
        self.assertEqual(labels, ["09:00-10:00 (1h 0m)", "12:00-13:00 (1h 0m)"])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_span_labels([Span(540, 600)], step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            round_span_labels([Span(541, 544)], 15)
